'use strict';
// Named baristas use paid contracts and a six-day roster in the existing sales ledger.
const CREW_BASE5={fresh,makeStore,nextWeek,validateSave,autoManager,setShifts5,shiftWages5,planAction4,decidePlan4};
const CREW_SKILLS5={speed:'Rychlost',coffee:'Příprava kávy',service:'Práce s hosty'};
