function barista5(pid,index,contract=2){return {pid,name:CREW_NAMES5[index%CREW_NAMES5.length],contract,payFactor:1,skills:{speed:66+index%9,coffee:66+(index*3)%9,service:66+(index*5)%9},days:Array(6).fill(true),periods:Array(3).fill(true),leave:null,xp:0,tenure:0,satisfaction:78,burnout:0,trained:0,history:[]};}
function crewStore5(s){if(s.franchise)return s;if(s.crew===undefined){const units=s.daily.shifts.reduce((a,n)=>a+n,0),employees=[];for(let i=0,left=units;left>0;i++,left-=2)employees.push(barista5('barista-'+s.id+'-'+i,i,Math.min(2,left)));s.crew={employees,roster:Array.from({length:6},()=>Array.from({length:3},()=>[])),manual:false,policy:{hire:false,train:false,budget:18000,reserve:3,quality:75,wait:10},last:null,history:[],decisions:[]};planCrew5(s);}return s;}
