fresh=function(...args){return ensureCrew5(CREW_BASE5.fresh(...args))};
makeStore=function(...args){return crewStore5(CREW_BASE5.makeStore(...args))};
state=ensureCrew5(state);
function crewStoreBy5(id){guard();const s=state.stores.find(s=>s.id===id);if(!s||s.franchise)throw Error('Vyber vlastní kavárnu.');return crewStore5(s);}
function crewAvailable5(p,day,period,week=state.week){return p.days[day]&&p.periods[period]&&!(p.leave&&p.leave.from<=week&&week<=p.leave.to);}
function crewPay5(s,p){return s.wage*p.contract/3*p.payFactor;}
shiftWages5=function(s){return s.crew&&!s.franchise?s.crew.employees.reduce((a,p)=>a+crewPay5(s,p),0):CREW_BASE5.shiftWages5(s);};
function crewShift5(s,day,period){if(!s.crew||s.franchise)return {heads:s.daily.shifts[period],factor:1,people:[]};const people=s.crew.roster[day][period].map(pid=>s.crew.employees.find(p=>p.pid===pid)).filter(p=>p&&crewAvailable5(p,day,period));return {heads:people.length,people,factor:people.length?people.reduce((a,p)=>a+clamp(1+(p.skills.speed-70)*.008+(p.skills.coffee-70)*.002+(p.skills.service-70)*.002-p.burnout*.003,.55,1.4),0)/people.length:1};}
function crewQuality5(s){if(!s.crew||s.franchise)return 0;const people=Array.from({length:6},(_,d)=>[0,1,2].flatMap(k=>crewShift5(s,d,k).people)).flat();return people.length?people.reduce((a,p)=>a+(p.skills.coffee-70)*.08+(p.skills.service-70)*.05-p.burnout*.025,0)/people.length:0;}
