 people.forEach((p,i)=>{add(0,i+1,p.contract);for(const k of periods)if(crewAvailable5(p,day,k))add(i+1,people.length+1+k,1);});periods.forEach(k=>add(people.length+1+k,sink,s.daily.shifts[k]));
