setShifts5=function(id,counts,automatic=false){const s=crewStoreBy5(id);CREW_BASE5.setShifts5(id,counts,automatic);if(!automatic){s.crew.manual=false;planCrew5(s);}};
autoManager=function(s){const decisions=CREW_BASE5.autoManager(s);crewStore5(s);planCrew5(s);return decisions;};
function crewStaffQuote5(s,target){const trial={...s,daily:{...s.daily,shifts:s.daily.shifts.map(n=>clamp(n+target-s.staff,0,7))},crew:{...s.crew,manual:false,employees:[...s.crew.employees]}},chosen=[];planCrew5(trial);while(crewGap5(trial)>0&&trial.crew.employees.length<24){const before=crewGap5(trial),candidate=state.baristaCandidates.filter(p=>!chosen.includes(p.pid)&&p.burnout<65&&p.satisfaction>=30).find(p=>{const roster=trial.crew.roster;try{trial.crew.employees.push(p);planCrew5(trial);return crewGap5(trial)<before;}finally{trial.crew.employees.pop();trial.crew.roster=roster;}});if(!candidate)break;chosen.push(candidate.pid);trial.crew.employees.push(candidate);planCrew5(trial);}return {candidatePids:chosen,cost:chosen.length*crewFee5(),weekly:chosen.reduce((a,pid)=>a+crewPay5(s,state.baristaCandidates.find(p=>p.pid===pid)),0),covered:crewGap5(trial)===0};}
planAction4=function(s){const action=CREW_BASE5.planAction4(s);if(action?.kind==='staff'&&s.crew){const quote=crewStaffQuote5(s,action.target);if(!quote.covered||s.crew.manual)return null;Object.assign(action,quote,{title:'Posílit jmenný tým a obsadit nové směny'});}return action;};
decidePlan4=function(id,approve,automatic=false){const p=state.empire.plans.find(p=>p.id===id),s=p&&state.stores.find(s=>s.id===p.store);if(!approve||p?.action.kind!=='staff'||!s?.crew)return CREW_BASE5.decidePlan4(id,approve,automatic);guard();if(s.crew.manual)throw Error('Ruční jmenný rozpis je chráněný. Nejprve povol přepočet jmen v Týmech.');const quote=crewStaffQuote5(s,p.action.target);if(!quote.covered||JSON.stringify(quote.candidatePids)!==JSON.stringify(p.action.candidatePids)||quote.cost!==p.action.cost||Math.abs(quote.weekly-p.action.weekly)>.01)throw Error('Nabídka baristů nebo mzdové náklady se změnily. Vyžádej nový plán.');if(state.cash<quote.cost+quote.weekly*2)throw Error('Nábor a dva týdny nových mezd nemají krytí.');const result=CREW_BASE5.decidePlan4(id,approve,automatic);for(const pid of quote.candidatePids)hireBarista5(s.id,pid);planCrew5(s);return result;};
function crewFee5(){return Math.max(2500,6000-state.departments.hr*750);}
