function releaseBarista5(id,pid){const {s,p}=baristaAt5(id,pid),cost=round(crewPay5(s,p));spend(cost);state.empire.pendingExpense+=cost;removeCrewPerson5(s,pid);state.baristaCandidates.push(p);log('Ukončení smlouvy: '+p.name,'Odstupné '+money(cost)+'. Osoba zůstává na trhu práce.');}
function transferBarista5(id,pid,target){const {s,p}=baristaAt5(id,pid),to=crewStoreBy5(target);if(to===s||loc(id).city!==loc(target).city||to.crew.employees.length>=24)throw Error('Přesun vyžaduje jinou vlastní kavárnu ve stejném městě a volný tým.');removeCrewPerson5(s,pid);to.crew.employees.push(p);planCrew5(to);log('Přesun: '+p.name,loc(id).name+' → '+loc(target).name+'. Identita, dovednosti a smlouva zachovány; sazba navazuje na mzdu cílové kavárny.');}
function availabilityBarista5(id,pid,days,periods){const {s,p}=baristaAt5(id,pid);if(!Array.isArray(days)||days.length!==6||!Array.isArray(periods)||periods.length!==3||[...days,...periods].some(x=>typeof x!=='boolean'))throw Error('Neplatná dostupnost.');p.days=[...days];p.periods=[...periods];planCrew5(s);}
function leaveBarista5(id,pid,from,weeks){const {s,p}=baristaAt5(id,pid);if(!Number.isInteger(from)||from<state.week||from>state.week+26||!Number.isInteger(weeks)||weeks<1||weeks>8)throw Error('Dovolená musí začít během 26 týdnů a trvat 1–8 týdnů.');p.leave={from,to:from+weeks-1};planCrew5(s);log('Dovolená: '+p.name,'Týdny '+from+'–'+p.leave.to+'. Mzda pokračuje, automatický rozpis využije dostupné kolegy.');}
