function raiseBarista5(id,pid){const {p}=baristaAt5(id,pid);if(p.payFactor>=2)throw Error('Mzda dosáhla dvojnásobku základu.');p.payFactor=Math.min(2,p.payFactor*1.1);p.satisfaction=clamp(p.satisfaction+8,0,100);}
