function setCrewPolicy5(id,p){const s=crewStoreBy5(id);if(!p||typeof p.hire!=='boolean'||typeof p.train!=='boolean'||!Number.isInteger(p.budget)||p.budget<0||p.budget>100000||!Number.isInteger(p.reserve)||p.reserve<1||p.reserve>8||!Number.isInteger(p.quality)||p.quality<50||p.quality>100||!Number.isInteger(p.wait)||p.wait<0||p.wait>30)throw Error('Mandát: rozpočet 0–100 000 Kč, rezerva 1–8 týdnů, cíl dovedností 50–100 a čekání 0–30 minut.');s.crew.policy={...p};}
